START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260707141525_AddUniversalPricingMatrix') THEN
    CREATE TABLE setup."FgsUniversalPricingService" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UniversalPricingServiceCode" character varying(50) NOT NULL,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalPricingService" PRIMARY KEY ("Id"),
        CONSTRAINT "AK_FgsUniversalPricingService_TenantId_CompanyId_Id" UNIQUE ("TenantId", "CompanyId", "Id"),
        CONSTRAINT "FK_FgsUniversalPricingService_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalPricingService" IS 'Defines Universal Pricing Services enabled and configured for a tenant company.';
    COMMENT ON COLUMN setup."FgsUniversalPricingService"."UniversalPricingServiceCode" IS 'Logical reference to glo.GloUniversalPricingService.ServiceCode. No cross-domain foreign key is enforced.';
    COMMENT ON COLUMN setup."FgsUniversalPricingService"."DisplayOrder" IS 'Controls the display sequence of the Universal Pricing Service for the company.';
    COMMENT ON COLUMN setup."FgsUniversalPricingService"."IsActive" IS 'Indicates whether the Universal Pricing Service is currently active for the company.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260707141525_AddUniversalPricingMatrix') THEN
    CREATE TABLE glo."GloUniversalPricingService" (
        "Id" smallint GENERATED BY DEFAULT AS IDENTITY,
        "ServiceCode" character varying(50) NOT NULL,
        "Name" character varying(100) NOT NULL,
        "Description" text,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "UpdatedOn" timestamptz,
        CONSTRAINT "PK_GloUniversalPricingService" PRIMARY KEY ("Id")
    );
    COMMENT ON TABLE glo."GloUniversalPricingService" IS 'Global seeded list of services supported by the Universal Pricing Matrix.';
    COMMENT ON COLUMN glo."GloUniversalPricingService"."ServiceCode" IS 'Stable system code used to identify the universal pricing service across domains.';
    COMMENT ON COLUMN glo."GloUniversalPricingService"."Name" IS 'User-facing service name.';
    COMMENT ON COLUMN glo."GloUniversalPricingService"."Description" IS 'Optional description of the universal pricing service.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260707141525_AddUniversalPricingMatrix') THEN
    CREATE TABLE setup."FgsUniversalMatrixAddOn" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UniversalPricingServiceId" bigint NOT NULL,
        "Name" character varying(150) NOT NULL,
        "UnitType" character varying(50) NOT NULL,
        "Price" numeric(18,4) NOT NULL DEFAULT 0.0,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalMatrixAddOn" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsUniversalMatrixAddOn_Price" CHECK ("Price" >= 0),
        CONSTRAINT "FK_FgsUniversalMatrixAddOn_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUniversalMatrixAddOn_FgsUniversalPricingService_TenantId_CompanyId_UniversalPricingServiceId" FOREIGN KEY ("TenantId", "CompanyId", "UniversalPricingServiceId") REFERENCES setup."FgsUniversalPricingService" ("TenantId", "CompanyId", "Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalMatrixAddOn" IS 'Stores company-specific optional add-ons available within the Universal Pricing Matrix.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixAddOn"."UniversalPricingServiceId" IS 'References the company-specific Universal Pricing Service configuration.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixAddOn"."UnitType" IS 'Pricing unit for the add-on, such as Flat Rate, Window, or Bed.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixAddOn"."Price" IS 'Company-specific price per add-on pricing unit.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260707141525_AddUniversalPricingMatrix') THEN
    CREATE TABLE setup."FgsUniversalMatrixFrequencyDiscount" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UniversalPricingServiceId" bigint NOT NULL,
        "Name" character varying(100) NOT NULL,
        "DiscountPercent" numeric(8,4) NOT NULL DEFAULT 0.0,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalMatrixFrequencyDiscount" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsUniversalMatrixFrequencyDiscount_DiscountPercent" CHECK ("DiscountPercent" >= 0 AND "DiscountPercent" <= 100),
        CONSTRAINT "FK_FgsUniversalMatrixFrequencyDiscount_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUniversalMatrixFrequencyDiscount_FgsUniversalPricingService_TenantId_CompanyId_UniversalPricingServiceId" FOREIGN KEY ("TenantId", "CompanyId", "UniversalPricingServiceId") REFERENCES setup."FgsUniversalPricingService" ("TenantId", "CompanyId", "Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalMatrixFrequencyDiscount" IS 'Stores company-specific service frequency options and their discount percentages.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixFrequencyDiscount"."UniversalPricingServiceId" IS 'References the company-specific Universal Pricing Service configuration.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixFrequencyDiscount"."DiscountPercent" IS 'Percentage discount applied based on the selected service frequency.';
    END IF;
END $EF$;

DO $EF$
