        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UniversalPricingServiceId" bigint NOT NULL,
        "ItemName" character varying(150) NOT NULL,
        "UnitType" character varying(50) NOT NULL,
        "BasePrice" numeric(18,4) NOT NULL DEFAULT 0.0,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalMatrixItem" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsUniversalMatrixItem_BasePrice" CHECK ("BasePrice" >= 0),
        CONSTRAINT "FK_FgsUniversalMatrixItem_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUniversalMatrixItem_FgsUniversalPricingService_TenantId_CompanyId_UniversalPricingServiceId" FOREIGN KEY ("TenantId", "CompanyId", "UniversalPricingServiceId") REFERENCES setup."FgsUniversalPricingService" ("TenantId", "CompanyId", "Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalMatrixItem" IS 'Stores company-specific Universal Pricing Matrix items and base prices.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixItem"."UniversalPricingServiceId" IS 'References the company-specific Universal Pricing Service configuration.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixItem"."UnitType" IS 'Pricing unit used by the matrix item, such as Flat Rate, Sqft, Linear Foot, Window, or Bed.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixItem"."BasePrice" IS 'Base price before tier, size, frequency, fee, add-on, tax, or other pricing adjustments.';
    END IF;
END $EF$;

DO $EF$
