        "Name" character varying(150) NOT NULL,
        "Amount" numeric(18,4) NOT NULL DEFAULT 0.0,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalMatrixOneTimeFee" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsUniversalMatrixOneTimeFee_Amount" CHECK ("Amount" >= 0),
        CONSTRAINT "FK_FgsUniversalMatrixOneTimeFee_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUniversalMatrixOneTimeFee_FgsUniversalPricingService_TenantId_CompanyId_UniversalPricingServiceId" FOREIGN KEY ("TenantId", "CompanyId", "UniversalPricingServiceId") REFERENCES setup."FgsUniversalPricingService" ("TenantId", "CompanyId", "Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalMatrixOneTimeFee" IS 'Stores company-specific one-time fees used by the Universal Pricing Matrix.';
