DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260707141525_AddUniversalPricingMatrix') THEN
    CREATE TABLE setup."FgsUniversalMatrixSizeTier" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UniversalPricingServiceId" bigint NOT NULL,
        "Name" character varying(100) NOT NULL,
        "Multiplier" numeric(8,4) NOT NULL DEFAULT 1.0,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsUniversalMatrixSizeTier" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsUniversalMatrixSizeTier_Multiplier" CHECK ("Multiplier" > 0),
        CONSTRAINT "FK_FgsUniversalMatrixSizeTier_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUniversalMatrixSizeTier_FgsUniversalPricingService_TenantId_CompanyId_UniversalPricingServiceId" FOREIGN KEY ("TenantId", "CompanyId", "UniversalPricingServiceId") REFERENCES setup."FgsUniversalPricingService" ("TenantId", "CompanyId", "Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsUniversalMatrixSizeTier" IS 'Stores company-specific size tiers and pricing multipliers for an enabled Universal Pricing Service.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixSizeTier"."UniversalPricingServiceId" IS 'References the company-specific Universal Pricing Service configuration.';
    COMMENT ON COLUMN setup."FgsUniversalMatrixSizeTier"."Multiplier" IS 'Company-specific multiplier applied for this size tier.';
    END IF;
END $EF$;

